#!/usr/bin/env python3\n\"\"\"\nRisk Categorization API Endpoints\nProvides REST API access to the enhanced risk categorization system\n\"\"\"\n\nfrom fastapi import APIRouter, HTTPException, Query\nfrom pydantic import BaseModel\nfrom typing import Dict, List, Optional, Any\nimport logging\nfrom datetime import datetime\n\nfrom assessment.risk_categorization import (\n    RiskCategorizationEngine, \n    RiskAssessment,\n    RiskLevel,\n    ConfidenceInterval\n)\nfrom database.models import get_session, Assessment, SectionScore\n\nlogger = logging.getLogger(__name__)\n\nrouter = APIRouter()\n\n# --- Pydantic Models ---\nclass RiskCategorizationRequest(BaseModel):\n    score: float\n    completion_rate: Optional[float] = 1.0\n    industry: Optional[str] = None\n    company_size: Optional[str] = None\n    historical_scores: Optional[List[float]] = None\n\nclass ConfidenceIntervalResponse(BaseModel):\n    lower_bound: float\n    upper_bound: float\n    confidence_level: float\n    margin_of_error: float\n    sample_size: int\n\nclass RiskAssessmentResponse(BaseModel):\n    score: float\n    risk_level: str\n    risk_label: str\n    risk_color: str\n    risk_description: str\n    action_required: str\n    confidence_interval: ConfidenceIntervalResponse\n    statistical_significance: float\n    benchmark_comparison: Dict[str, Any]\n    trend_analysis: Dict[str, Any]\n    recommendations: List[str]\n\n# --- API Endpoints ---\n\n@router.post(\"/risk/categorize\", response_model=RiskAssessmentResponse, tags=[\"Risk Categorization\"])\ndef categorize_risk(request: RiskCategorizationRequest):\n    \"\"\"Categorize risk level with comprehensive statistical analysis\"\"\"\n    try:\n        # Validate input\n        if not 0 <= request.score <= 100:\n            raise HTTPException(status_code=400, detail=\"Score must be between 0 and 100\")\n        \n        if request.completion_rate and not 0 <= request.completion_rate <= 1:\n            raise HTTPException(status_code=400, detail=\"Completion rate must be between 0 and 1\")\n        \n        # Perform risk categorization\n        assessment = RiskCategorizationEngine.categorize_risk(\n            score=request.score,\n            completion_rate=request.completion_rate or 1.0,\n            industry=request.industry,\n            company_size=request.company_size,\n            historical_scores=request.historical_scores\n        )\n        \n        # Convert to response format\n        response = RiskAssessmentResponse(\n            score=assessment.score,\n            risk_level=assessment.risk_level.value,\n            risk_label=assessment.risk_threshold.label,\n            risk_color=assessment.risk_threshold.color,\n            risk_description=assessment.risk_threshold.description,\n            action_required=assessment.risk_threshold.action_required,\n            confidence_interval=ConfidenceIntervalResponse(\n                lower_bound=assessment.confidence_interval.lower_bound,\n                upper_bound=assessment.confidence_interval.upper_bound,\n                confidence_level=assessment.confidence_interval.confidence_level,\n                margin_of_error=assessment.confidence_interval.margin_of_error,\n                sample_size=assessment.confidence_interval.sample_size\n            ),\n            statistical_significance=assessment.statistical_significance,\n            benchmark_comparison=assessment.benchmark_comparison,\n            trend_analysis=assessment.trend_analysis,\n            recommendations=assessment.recommendations\n        )\n        \n        return response\n        \n    except HTTPException:\n        raise\n    except Exception as e:\n        logger.error(f\"Error categorizing risk: {str(e)}\")\n        raise HTTPException(status_code=500, detail=f\"Failed to categorize risk: {str(e)}\")\n\n@router.get(\"/risk/assessment/{assessment_id}/categorization\", response_model=RiskAssessmentResponse, tags=[\"Risk Categorization\"])\ndef get_assessment_risk_categorization(assessment_id: int,\n                                     industry: Optional[str] = Query(None, description=\"Industry sector\"),\n                                     company_size: Optional[str] = Query(None, description=\"Company size (small/medium/large/enterprise)\")):\n    \"\"\"Get comprehensive risk categorization for a specific assessment\"\"\"\n    try:\n        db = get_session()\n        \n        # Get assessment\n        assessment = db.query(Assessment).filter(Assessment.id == assessment_id).first()\n        if not assessment:\n            raise HTTPException(status_code=404, detail=f\"Assessment {assessment_id} not found\")\n        \n        if not assessment.overall_score:\n            raise HTTPException(status_code=400, detail=\"Assessment has not been scored yet\")\n        \n        # Get section scores for completion rate calculation\n        section_scores = db.query(SectionScore).filter(\n            SectionScore.assessment_id == assessment_id\n        ).all()\n        \n        total_questions = sum(s.total_questions or 0 for s in section_scores)\n        answered_questions = sum(s.questions_answered or 0 for s in section_scores)\n        completion_rate = answered_questions / total_questions if total_questions > 0 else 1.0\n        \n        # Get historical scores for trend analysis\n        historical_assessments = db.query(Assessment).filter(\n            Assessment.company_id == assessment.company_id,\n            Assessment.overall_score.isnot(None),\n            Assessment.id < assessment_id  # Only previous assessments\n        ).order_by(Assessment.created_at).all()\n        \n        historical_scores = [a.overall_score for a in historical_assessments if a.overall_score is not None]\n        \n        db.close()\n        \n        # Perform risk categorization\n        risk_assessment = RiskCategorizationEngine.categorize_risk(\n            score=assessment.overall_score,\n            completion_rate=completion_rate,\n            industry=industry,\n            company_size=company_size,\n            historical_scores=historical_scores if len(historical_scores) > 1 else None\n        )\n        \n        # Convert to response format\n        response = RiskAssessmentResponse(\n            score=risk_assessment.score,\n            risk_level=risk_assessment.risk_level.value,\n            risk_label=risk_assessment.risk_threshold.label,\n            risk_color=risk_assessment.risk_threshold.color,\n            risk_description=risk_assessment.risk_threshold.description,\n            action_required=risk_assessment.risk_threshold.action_required,\n            confidence_interval=ConfidenceIntervalResponse(\n                lower_bound=risk_assessment.confidence_interval.lower_bound,\n                upper_bound=risk_assessment.confidence_interval.upper_bound,\n                confidence_level=risk_assessment.confidence_interval.confidence_level,\n                margin_of_error=risk_assessment.confidence_interval.margin_of_error,\n                sample_size=risk_assessment.confidence_interval.sample_size\n            ),\n            statistical_significance=risk_assessment.statistical_significance,\n            benchmark_comparison=risk_assessment.benchmark_comparison,\n            trend_analysis=risk_assessment.trend_analysis,\n            recommendations=risk_assessment.recommendations\n        )\n        \n        return response\n        \n    except HTTPException:\n        raise\n    except Exception as e:\n        logger.error(f\"Error getting assessment risk categorization: {str(e)}\")\n        raise HTTPException(status_code=500, detail=f\"Failed to get risk categorization: {str(e)}\")\n\n@router.get(\"/risk/matrix\", tags=[\"Risk Categorization\"])\ndef get_risk_matrix():\n    \"\"\"Get complete risk categorization matrix with thresholds and benchmarks\"\"\"\n    try:\n        return RiskCategorizationEngine.get_risk_matrix()\n    except Exception as e:\n        logger.error(f\"Error getting risk matrix: {str(e)}\")\n        raise HTTPException(status_code=500, detail=f\"Failed to get risk matrix: {str(e)}\")\n\n@router.get(\"/risk/benchmarks/{industry}\", tags=[\"Risk Categorization\"])\ndef get_industry_benchmark(industry: str):\n    \"\"\"Get benchmark data for a specific industry\"\"\"\n    try:\n        benchmarks = RiskCategorizationEngine.INDUSTRY_BENCHMARKS\n        \n        if industry not in benchmarks:\n            available_industries = list(benchmarks.keys())\n            raise HTTPException(\n                status_code=404, \n                detail=f\"Industry '{industry}' not found. Available industries: {available_industries}\"\n            )\n        \n        return {\n            \"industry\": industry,\n            \"benchmark_data\": benchmarks[industry],\n            \"last_updated\": datetime.utcnow().isoformat(),\n            \"methodology\": \"Statistical analysis of industry assessments with 95% confidence intervals\"\n        }\n        \n    except HTTPException:\n        raise\n    except Exception as e:\n        logger.error(f\"Error getting industry benchmark: {str(e)}\")\n        raise HTTPException(status_code=500, detail=f\"Failed to get industry benchmark: {str(e)}\")\n\n@router.get(\"/risk/confidence-interval\", tags=[\"Risk Categorization\"])\ndef calculate_confidence_interval(score: float = Query(..., description=\"Assessment score (0-100)\"),\n                                completion_rate: float = Query(1.0, description=\"Assessment completion rate (0-1)\"),\n                                industry: Optional[str] = Query(None, description=\"Industry for benchmark data\"),\n                                confidence_level: float = Query(0.95, description=\"Confidence level (0.90, 0.95, 0.99)\")):\n    \"\"\"Calculate confidence interval for a given score\"\"\"\n    try:\n        # Validate inputs\n        if not 0 <= score <= 100:\n            raise HTTPException(status_code=400, detail=\"Score must be between 0 and 100\")\n        \n        if not 0 <= completion_rate <= 1:\n            raise HTTPException(status_code=400, detail=\"Completion rate must be between 0 and 1\")\n        \n        if confidence_level not in [0.90, 0.95, 0.99]:\n            raise HTTPException(status_code=400, detail=\"Confidence level must be 0.90, 0.95, or 0.99\")\n        \n        # Calculate confidence interval\n        confidence_interval = RiskCategorizationEngine._calculate_confidence_interval(\n            score, completion_rate, industry, confidence_level\n        )\n        \n        return {\n            \"score\": score,\n            \"completion_rate\": completion_rate,\n            \"industry\": industry,\n            \"confidence_interval\": {\n                \"lower_bound\": confidence_interval.lower_bound,\n                \"upper_bound\": confidence_interval.upper_bound,\n                \"confidence_level\": confidence_interval.confidence_level,\n                \"margin_of_error\": confidence_interval.margin_of_error,\n                \"sample_size\": confidence_interval.sample_size\n            },\n            \"interpretation\": f\"We are {int(confidence_level*100)}% confident that the true score lies between {confidence_interval.lower_bound} and {confidence_interval.upper_bound}\"\n        }\n        \n    except HTTPException:\n        raise\n    except Exception as e:\n        logger.error(f\"Error calculating confidence interval: {str(e)}\")\n        raise HTTPException(status_code=500, detail=f\"Failed to calculate confidence interval: {str(e)}\")\n\n@router.get(\"/risk/percentile\", tags=[\"Risk Categorization\"])\ndef calculate_industry_percentile(score: float = Query(..., description=\"Assessment score (0-100)\"),\n                                industry: str = Query(..., description=\"Industry sector\")):\n    \"\"\"Calculate industry percentile ranking for a given score\"\"\"\n    try:\n        # Validate inputs\n        if not 0 <= score <= 100:\n            raise HTTPException(status_code=400, detail=\"Score must be between 0 and 100\")\n        \n        benchmarks = RiskCategorizationEngine.INDUSTRY_BENCHMARKS\n        if industry not in benchmarks:\n            available_industries = list(benchmarks.keys())\n            raise HTTPException(\n                status_code=404,\n                detail=f\"Industry '{industry}' not found. Available industries: {available_industries}\"\n            )\n        \n        benchmark = benchmarks[industry]\n        percentiles = benchmark[\"percentiles\"]\n        \n        # Calculate approximate percentile\n        if score >= percentiles[\"90th\"]:\n            percentile_rank = 90 + (score - percentiles[\"90th\"]) / (100 - percentiles[\"90th\"]) * 10\n        elif score >= percentiles[\"75th\"]:\n            percentile_rank = 75 + (score - percentiles[\"75th\"]) / (percentiles[\"90th\"] - percentiles[\"75th\"]) * 15\n        elif score >= percentiles[\"50th\"]:\n            percentile_rank = 50 + (score - percentiles[\"50th\"]) / (percentiles[\"75th\"] - percentiles[\"50th\"]) * 25\n        elif score >= percentiles[\"25th\"]:\n            percentile_rank = 25 + (score - percentiles[\"25th\"]) / (percentiles[\"50th\"] - percentiles[\"25th\"]) * 25\n        elif score >= percentiles[\"10th\"]:\n            percentile_rank = 10 + (score - percentiles[\"10th\"]) / (percentiles[\"25th\"] - percentiles[\"10th\"]) * 15\n        else:\n            percentile_rank = (score / percentiles[\"10th\"]) * 10\n        \n        percentile_rank = max(0, min(100, percentile_rank))  # Clamp to 0-100\n        \n        return {\n            \"score\": score,\n            \"industry\": industry,\n            \"percentile_rank\": round(percentile_rank, 1),\n            \"industry_average\": benchmark[\"average_score\"],\n            \"performance_vs_average\": round(score - benchmark[\"average_score\"], 2),\n            \"sample_size\": benchmark[\"sample_size\"],\n            \"interpretation\": f\"Your score is better than {percentile_rank:.1f}% of organizations in the {industry} industry\"\n        }\n        \n    except HTTPException:\n        raise\n    except Exception as e:\n        logger.error(f\"Error calculating industry percentile: {str(e)}\")\n        raise HTTPException(status_code=500, detail=f\"Failed to calculate industry percentile: {str(e)}\")\n\n@router.post(\"/risk/trend-analysis\", tags=[\"Risk Categorization\"])\ndef analyze_risk_trends(historical_scores: List[float]):\n    \"\"\"Analyze risk trends from historical assessment scores\"\"\"\n    try:\n        if len(historical_scores) < 2:\n            raise HTTPException(status_code=400, detail=\"At least 2 historical scores required for trend analysis\")\n        \n        if not all(0 <= score <= 100 for score in historical_scores):\n            raise HTTPException(status_code=400, detail=\"All scores must be between 0 and 100\")\n        \n        # Use the last score as current score for trend analysis\n        current_score = historical_scores[-1]\n        previous_scores = historical_scores[:-1]\n        \n        trend_analysis = RiskCategorizationEngine._analyze_trends(current_score, previous_scores)\n        \n        return {\n            \"current_score\": current_score,\n            \"historical_scores\": previous_scores,\n            \"trend_analysis\": trend_analysis,\n            \"score_range\": {\n                \"minimum\": min(historical_scores),\n                \"maximum\": max(historical_scores),\n                \"average\": round(sum(historical_scores) / len(historical_scores), 2)\n            },\n            \"assessment_count\": len(historical_scores)\n        }\n        \n    except HTTPException:\n        raise\n    except Exception as e:\n        logger.error(f\"Error analyzing risk trends: {str(e)}\")\n        raise HTTPException(status_code=500, detail=f\"Failed to analyze risk trends: {str(e)}\")\n\n@router.get(\"/risk/visualization-data/{assessment_id}\", tags=[\"Risk Categorization\"])\ndef get_risk_visualization_data(assessment_id: int,\n                              industry: Optional[str] = Query(None, description=\"Industry for benchmarking\")):\n    \"\"\"Get data optimized for risk visualization components\"\"\"\n    try:\n        db = get_session()\n        \n        # Get assessment\n        assessment = db.query(Assessment).filter(Assessment.id == assessment_id).first()\n        if not assessment:\n            raise HTTPException(status_code=404, detail=f\"Assessment {assessment_id} not found\")\n        \n        if not assessment.overall_score:\n            raise HTTPException(status_code=400, detail=\"Assessment has not been scored yet\")\n        \n        # Get section scores\n        section_scores = db.query(SectionScore).filter(\n            SectionScore.assessment_id == assessment_id\n        ).all()\n        \n        db.close()\n        \n        # Calculate completion rate\n        total_questions = sum(s.total_questions or 0 for s in section_scores)\n        answered_questions = sum(s.questions_answered or 0 for s in section_scores)\n        completion_rate = answered_questions / total_questions if total_questions > 0 else 1.0\n        \n        # Get risk categorization\n        risk_assessment = RiskCategorizationEngine.categorize_risk(\n            score=assessment.overall_score,\n            completion_rate=completion_rate,\n            industry=industry\n        )\n        \n        # Prepare visualization data\n        visualization_data = {\n            \"overall_score\": {\n                \"value\": assessment.overall_score,\n                \"risk_level\": risk_assessment.risk_level.value,\n                \"color\": risk_assessment.risk_threshold.color,\n                \"label\": risk_assessment.risk_threshold.label\n            },\n            \"confidence_interval\": {\n                \"lower\": risk_assessment.confidence_interval.lower_bound,\n                \"upper\": risk_assessment.confidence_interval.upper_bound,\n                \"margin\": risk_assessment.confidence_interval.margin_of_error\n            },\n            \"risk_thresholds\": [\n                {\"min\": 0, \"max\": 40, \"label\": \"Critical\", \"color\": \"#dc2626\"},\n                {\"min\": 40, \"max\": 60, \"label\": \"High\", \"color\": \"#ea580c\"},\n                {\"min\": 60, \"max\": 80, \"label\": \"Medium\", \"color\": \"#ca8a04\"},\n                {\"min\": 80, \"max\": 100, \"label\": \"Low\", \"color\": \"#16a34a\"}\n            ],\n            \"section_breakdown\": [\n                {\n                    \"section_id\": s.section_id,\n                    \"score\": s.score,\n                    \"completion_rate\": (s.questions_answered or 0) / (s.total_questions or 1) * 100,\n                    \"risk_level\": RiskCategorizationEngine._get_risk_level(s.score or 0).value\n                }\n                for s in section_scores\n            ],\n            \"benchmark_comparison\": risk_assessment.benchmark_comparison if industry else None,\n            \"statistical_significance\": risk_assessment.statistical_significance\n        }\n        \n        return visualization_data\n        \n    except HTTPException:\n        raise\n    except Exception as e:\n        logger.error(f\"Error getting risk visualization data: {str(e)}\")\n        raise HTTPException(status_code=500, detail=f\"Failed to get risk visualization data: {str(e)}\")"